import type { Checklist, Criterion, Phase } from '../types';

const slug = (s: string) =>
  s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

/**
 * Parses src/checklist.md (generated by scripts/json_to_md.py):
 *
 *   # Checklist title
 *   > Subtitle
 *   ## Phase name
 *   Tools: a, b, c
 *   ### id | SC | Title | Level
 *   - Section 508: ...
 *   - ANDI module: ...
 *   - Web: ...
 *   - PDF: ...
 *   - Hint: ...        (repeatable)
 */
export function parseChecklist(md: string): Checklist {
  const checklist: Checklist = { title: '', subtitle: '', phases: [] };
  const seen = new Set<string>();
  let phase: Phase | null = null;
  let item: Criterion | null = null;

  const lines = md.replace(/<!--[\s\S]*?-->/g, '').split(/\r?\n/);
  for (const raw of lines) {
    const line = raw.trim();
    let m: RegExpMatchArray | null;

    if ((m = line.match(/^###\s+(.+)$/))) {
      if (!phase) continue;
      const [id = '', sc = '', name = '', level = ''] = m[1].split('|').map((s) => s.trim());
      let key = id || `${phase.id}:${sc}`;
      for (let n = 2; seen.has(key); n++) key = `${id}-${n}`;
      seen.add(key);
      item = { key, sc, name, level, section508: '', andiModule: '', webCheck: '', pdfCheck: '', hints: [] };
      phase.criteria.push(item);
    } else if ((m = line.match(/^##\s+(.+)$/))) {
      phase = { id: slug(m[1]), title: m[1].trim(), tools: [], criteria: [] };
      checklist.phases.push(phase);
      item = null;
    } else if ((m = line.match(/^#\s+(.+)$/))) {
      checklist.title = m[1].trim();
    } else if ((m = line.match(/^>\s*(.+)$/)) && !phase) {
      checklist.subtitle = m[1].trim();
    } else if ((m = line.match(/^Tools:\s*(.+)$/i)) && phase && !item) {
      phase.tools = m[1].split(',').map((s) => s.trim()).filter(Boolean);
    } else if ((m = line.match(/^[-*]\s+([^:]+):\s*(.+)$/)) && item) {
      const field = m[1].trim().toLowerCase();
      const value = m[2].trim();
      if (field === 'section 508') item.section508 = value;
      else if (field === 'andi module') item.andiModule = value;
      else if (field === 'web') item.webCheck = value;
      else if (field === 'pdf') item.pdfCheck = value;
      else if (field === 'hint') item.hints.push(value);
    }
  }

  checklist.phases = checklist.phases.filter((p) => p.criteria.length > 0);
  return checklist;
}
